@pytest.mark.parametrize("shape,kwargs,dtype,layout", _DEMOTED, ids=_DEMOTED_IDS)
def test_tilize_codegen_demotion(device, shape, kwargs, dtype, layout):
    x = _make_input(shape, dtype)
    xt = ttnn.from_torch(x, dtype=dtype, layout=layout, device=device)
    golden = ttnn.to_torch(ttnn.tilize(xt, **kwargs, implementation=_NATIVE))
    entries_before = device.num_program_cache_entries()
    out = ttnn.tilize(xt, **kwargs, implementation=_ROUTED)
    assert_equal(golden, ttnn.to_torch(out))
    msg = "auto routed a perf-demoted case to codegen (program cache grew); expected native fallback"
    assert device.num_program_cache_entries() == entries_before, msg


_CACHE_HIT = [
    (
        [32, 32],
        {"memory_config": ttnn.MemoryConfig(ttnn.TensorMemoryLayout.INTERLEAVED, ttnn.BufferType.DRAM)},
        ttnn.int32,
        ttnn.ROW_MAJOR_LAYOUT,
    ),
]
_CACHE_HIT_IDS = [
    "[32, 32]|memory_config=dram|int32|row_major",
]


@pytest.mark.parametrize("shape,kwargs,dtype,layout", _CACHE_HIT, ids=_CACHE_HIT_IDS)
def test_tilize_codegen_program_cache_hit(device, shape, kwargs, dtype, layout):
    x = _make_input(shape, dtype)
    xt = ttnn.from_torch(x, dtype=dtype, layout=layout, device=device)
    golden = ttnn.to_torch(ttnn.tilize(xt, **kwargs, implementation=_NATIVE))
    assert_equal(golden, ttnn.to_torch(ttnn.tilize(xt, **kwargs, implementation=_CODEGEN)))
    entries_after_miss = device.num_program_cache_entries()
    # Same spec, a distinct allocation: the cached program must rebind its Buffer*s
    # instead of reusing the first dispatch's addresses.
    yt = ttnn.from_torch(_make_input(shape, dtype), dtype=dtype, layout=layout, device=device)
    second_golden = ttnn.to_torch(ttnn.tilize(yt, **kwargs, implementation=_NATIVE))
    assert_equal(second_golden, ttnn.to_torch(ttnn.tilize(yt, **kwargs, implementation=_CODEGEN)))
    msg = "second forced-codegen dispatch missed the program cache"
    assert device.num_program_cache_entries() == entries_after_miss, msg


_SELECTOR_CASE = (
    [32, 32],
    {"memory_config": ttnn.MemoryConfig(ttnn.TensorMemoryLayout.INTERLEAVED, ttnn.BufferType.DRAM)},
    ttnn.int32,
    ttnn.ROW_MAJOR_LAYOUT,
)


@pytest.mark.parametrize("selector", ["", "Codegen", "codgen", "default"])
def test_tilize_codegen_rejects_an_unknown_implementation(device, expect_error, selector):
    shape, kwargs, dtype, layout = _SELECTOR_CASE
    xt = ttnn.from_torch(_make_input(shape, dtype), dtype=dtype, layout=layout, device=device)
    # The selector is parsed on every call, including ones a front-end shortcut would
    # otherwise answer without dispatching, so an unknown value never passes silently.
    with expect_error(RuntimeError, "unknown implementation selector"):
        ttnn.tilize(xt, **kwargs, implementation=selector)
